'use strict';
const A=window.ZomatoAnalytics, DATA=window.ZOMATO_DATA.records, AUDIT=window.ZOMATO_DATA.audit;
const $=id=>document.getElementById(id), fmt=n=>n===null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:0}), pct=n=>n===null?'—':(n*100).toFixed(1)+'%', esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={market:'1',city:'',cuisine:'',price:'',delivery:'',rating:'',search:''},selected=[],page=0;
const currency={1:'₹',14:'A$',30:'R$',37:'C$',94:'Rp ',148:'NZ$',166:'QR ',184:'S$',189:'R ',191:'LKR ',208:'TL ',214:'AED ',215:'£',216:'US$'};
const money=(n,rows)=>n===null?'—':(currency[rows[0]?.country]||'')+fmt(n);
function options(id,values,empty){const el=$(id),previous=state[id];el.replaceChildren(new Option(empty,''),...values.map(([value,label])=>new Option(label,value)));if(values.some(([v])=>String(v)===String(previous)))el.value=previous;else {state[id]='';el.value='';}}
function dependentOptions(){const base=DATA.filter(r=>!state.market||String(r.country)===state.market);options('city',[...new Set(base.map(r=>r.city))].sort().map(x=>[x,x]),'All cities');const local=base.filter(r=>!state.city||r.city===state.city);options('cuisine',[...new Set(local.flatMap(r=>r.cuisines))].sort().map(x=>[x,x]),'All cuisines');}
function barChart(id,items,color){if(!items.length){$(id).innerHTML='<p class="empty">No matching restaurants.</p>';return;}const max=Math.max(...items.map(x=>x.count));$(id).innerHTML=items.slice(0,8).map(x=>`<div class="bar-row"><span class="bar-label" title="${esc(x.name)}">${esc(x.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${100*x.count/max}%;background:${color}"></div></div><span class="bar-value">${fmt(x.count)}</span></div>`).join('');}
function renderScatter(rows,m){const target=$('scatter');if(!m.priceComparable){$('scatter-note').textContent='Price comparisons require one market with a usable source currency.';target.innerHTML='<div class="empty">Select a single market to compare cost and rating. Philippines pricing is unavailable because its source currency needs verification.</div>';return;}
  const valid=rows.filter(r=>r.rating!==null&&r.cost!==null);$('scatter-note').textContent=`${fmt(valid.length)} rated listings with positive costs · cost for two in ${currency[rows[0]?.country]||'source units'} · larger circles contain more restaurants`;
  if(!valid.length){target.innerHTML='<p class="empty">No rated restaurants with usable prices in this selection.</p>';return;}
  const max=Math.max(...valid.map(r=>r.cost)),limit=Math.ceil(max/100)*100||100,W=1050,H=320,L=55,R=25,T=20,B=50,pw=W-L-R,ph=H-T-B;
  const cells=new Map();for(const r of valid){const x=Math.min(49,Math.floor(r.cost/limit*50)),y=Math.min(29,Math.floor(r.rating/5*30)),key=x+':'+y;if(!cells.has(key))cells.set(key,{n:0,cost:0,rating:0});const c=cells.get(key);c.n++;c.cost+=r.cost;c.rating+=r.rating;}
  const yPos=n=>T+ph*(1-n/5), xPos=n=>L+pw*n/limit;let svg=`<svg class="scatter-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Binned scatterplot of cost for two versus aggregate rating for ${valid.length} restaurants"><title>Cost for two versus rating</title>`;
  for(let i=0;i<=5;i++)svg+=`<line x1="${L}" x2="${W-R}" y1="${yPos(i)}" y2="${yPos(i)}" stroke="#edf0f4"/><text x="${L-15}" y="${yPos(i)+4}" text-anchor="end">${i.toFixed(1)}</text>`;
  for(let i=0;i<=5;i++)svg+=`<text x="${xPos(limit*i/5)}" y="${H-25}" text-anchor="middle">${fmt(limit*i/5)}</text>`;
  for(const c of [...cells.values()].sort((a,b)=>b.n-a.n)){const cost=c.cost/c.n,rating=c.rating/c.n;svg+=`<circle cx="${xPos(cost)}" cy="${yPos(rating)}" r="${Math.min(14,2+Math.sqrt(c.n)*.85)}" fill="#cf3448" fill-opacity=".32" stroke="#b52940" stroke-opacity=".36"><title>${c.n} restaurants · mean cost ${esc(money(cost,rows))} · mean rating ${rating.toFixed(2)}</title></circle>`;}
  svg+=`<text x="${L+pw/2}" y="${H-4}" text-anchor="middle">Average cost for two (${esc(currency[rows[0]?.country]||'source units')})</text><text x="15" y="${T+ph/2}" transform="rotate(-90 15 ${T+ph/2})" text-anchor="middle">Rating</text></svg>`;target.innerHTML=svg;
}
function render(){selected=A.filter(DATA,state);const m=A.metrics(selected),cities=A.groups(selected,'city'),cuisines=A.groups(selected,'cuisines'),market=state.market?AUDIT.countries[state.market]:'All markets';$('selection').textContent=`${fmt(m.count)} of ${fmt(DATA.length)} restaurants · ${market} · ${fmt(m.cities)} cities`;
  const cards=[['Restaurants',fmt(m.count),'Distinct restaurant listings'],['Average rating',m.avgRating===null?'—':m.avgRating.toFixed(2),`${fmt(m.rated)} rated listings · out of 5`],['Median cost for two',money(m.medianCost,selected),m.priceComparable?'Positive source costs only':'Select one verified market'],['Online delivery',pct(m.delivery),'Share offering online delivery'],['Table booking',pct(m.booking),'Share offering table booking'],['Total votes',fmt(m.votes),'Recorded votes, not orders']];$('kpis').innerHTML=cards.map(([label,value,note])=>`<article class="kpi"><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-note">${note}</div></article>`).join('');
  $('insight').innerHTML=m.count?`<strong>IN THIS SELECTION</strong><span>${esc(cities[0].name)} accounts for <b>${pct(cities[0].count/m.count)}</b> of listings. <b>${pct(m.unrated/m.count)}</b> are unrated${cuisines[0]?`, and ${esc(cuisines[0].name)} is the most frequently listed cuisine`:''}.</span>`:'<strong>No matches</strong><span>Try a broader market, remove a filter or clear your search.</span>';
  barChart('cities',cities,'#cf3448');barChart('cuisines',cuisines,'#38887c');
  const distribution=A.distribution(selected);$('ratings').innerHTML=`<div class="rating-head"><strong>${m.avgRating===null?'—':m.avgRating.toFixed(2)}</strong><span>/ 5 average across rated restaurants</span></div><div class="rating-stack">${distribution.map(x=>`<div style="width:${m.count?100*x.count/m.count:0}%;background:${x.color}" title="${esc(x.name)}: ${fmt(x.count)}"></div>`).join('')}</div><div class="rating-legend">${distribution.map(x=>`<div class="legend-item"><span class="legend-name"><i class="swatch" style="background:${x.color}"></i>${x.name}</span><strong>${fmt(x.count)} <span style="font-weight:400;color:#677282">(${m.count?pct(x.count/m.count):'—'})</span></strong></div>`).join('')}</div>`;
  const tiers=A.groups(selected,'priceRange').sort((a,b)=>a.name-b.name),names=['','Budget','Mid-range','Premium','Luxury'];$('tiers').innerHTML=tiers.length?tiers.map(x=>`<div class="tier-row"><span>${names[x.name]}<small>${fmt(x.count)} restaurants</small></span><div class="bar-track"><div class="bar-fill" style="width:${100*x.count/m.count}%;background:#697e8b"></div></div><span class="tier-rating">${x.avgRating===null?'—':x.avgRating.toFixed(2)}<small>avg rating</small></span></div>`).join(''):'<p class="empty">No matching restaurants.</p>';
  renderScatter(selected,m);renderTable();
}
function renderTable(){const sort=$('sort').value;let rows=[...selected];rows.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='cost'?(a.cost??Infinity)-(b.cost??Infinity):sort==='rating'?(b.rating??-1)-(a.rating??-1)||b.votes-a.votes:b.votes-a.votes);const pages=Math.max(1,Math.ceil(rows.length/15));page=Math.min(page,pages-1);$('restaurant-rows').innerHTML=rows.slice(page*15,page*15+15).map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.locality)}${r.textIssue?' · source text issue':''}</small></td><td>${esc(r.city)}<small>${esc(r.market)}</small></td><td>${esc(r.cuisines.join(', ')||'Not supplied')}</td><td><span class="rating-pill">${r.rating===null?'Unrated':r.rating.toFixed(1)}</span></td><td>${r.cost===null?'Unavailable':fmt(r.cost)}<small>${esc(r.currency)}${r.country===162?' · verify currency':''}</small></td><td>${fmt(r.votes)}</td><td>${r.delivery?'Yes':'No'}</td></tr>`).join('')||'<tr><td colspan="7" class="empty">No matching restaurants. Clear your filters to start again.</td></tr>';$('page-status').textContent=rows.length?`${fmt(page*15+1)}–${fmt(Math.min(page*15+15,rows.length))} of ${fmt(rows.length)} restaurants`:'0 restaurants';$('prev').disabled=page===0;$('next').disabled=page>=pages-1;}
function setView(view){for(const el of document.querySelectorAll('.view'))el.hidden=el.id!==view;for(const button of document.querySelectorAll('.nav')){const active=button.dataset.view===view;button.classList.toggle('active',active);if(active)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}$('view-title').textContent={overview:'A closer look at dining.',explorer:'Every restaurant, in detail.',methodology:'Behind the numbers.'}[view];}
function reset(){state={market:'1',city:'',cuisine:'',price:'',delivery:'',rating:'',search:''};for(const key of Object.keys(state))$(key).value=state[key];dependentOptions();page=0;render();}
options('market',Object.entries(AUDIT.countries).sort((a,b)=>a[1].localeCompare(b[1])),'All markets');$('market').value='1';dependentOptions();
for(const key of ['market','city','cuisine','price','delivery','rating'])$(key).addEventListener('change',()=>{state[key]=$(key).value;if(key==='market'){state.city='';state.cuisine='';dependentOptions();}if(key==='city'){state.cuisine='';dependentOptions();}page=0;render();});
$('search').addEventListener('input',()=>{state.search=$('search').value;page=0;render();});$('reset').addEventListener('click',reset);$('sort').addEventListener('change',()=>{page=0;renderTable();});$('prev').addEventListener('click',()=>{page--;renderTable();});$('next').addEventListener('click',()=>{page++;renderTable();});for(const b of document.querySelectorAll('.nav'))b.addEventListener('click',()=>setView(b.dataset.view));
$('export').addEventListener('click',()=>{const fields=['id','name','market','city','locality','cuisines','rating','cost','currency','votes','delivery','booking','priceRange'];const safe=v=>{let s=Array.isArray(v)?v.join('; '):v==null?'':String(v);if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const csv=[fields.join(','),...selected.map(r=>fields.map(f=>safe(r[f])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'})),link=document.createElement('a');link.href=url;link.download='dinemetric-atlas-restaurants.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('audit').innerHTML=[['Source listings',AUDIT.sourceRows],['Unrated restaurants',AUDIT.unrated],['Missing cuisine entries',AUDIT.missingCuisines],['Unavailable costs',AUDIT.nonPositiveCost],['Zero coordinate pairs',AUDIT.zeroCoordinates],['Rows with damaged text',AUDIT.encodingAffectedRows]].map(([label,n])=>`<div class="audit-card"><b>${fmt(n)}</b>${label}</div>`).join('');render();
if(document.modelContext?.registerTool){const tool={name:'read_restaurant_selection',title:'Read restaurant selection',description:'Read metrics for the currently visible dashboard filter selection. Does not change filters.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {filters:{...state},metrics:A.metrics(selected)};}};try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}
